oldkeys=set(zip(old.vt_symbol,old.date));j=clean.merge(m,on=['vt_symbol','date'],suffixes=('_C','_M'),validate='one_to_one');j['year']=j.date.str[:4];j['origin']=['original_legacy_key' if (r.vt_symbol,r.date) in oldkeys else 'new_missing_key_overlay' for r in j.itertuples()];j['price_exact']=np.logical_and.reduce([np.isclose(j[a],j[b],rtol=0,atol=1e-8) for a,b in [('open','open_price'),('high','high_price'),('low','low_price'),('close','close_price')]])
for field,cfield,mfield in [('volume','volume_C','volume_M'),('OI','close_oi','open_interest_M')]:
 j[field+'_positive']=j[cfield].gt(0)&j[mfield].gt(0);j[field+'_1x']=j[field+'_positive']&np.isclose(j[mfield],j[cfield],rtol=0,atol=1e-8);j[field+'_2x']=j[field+'_positive']&np.isclose(j[mfield],j[cfield]*2,rtol=0,atol=1e-8)
 j[field+'_ratio']=j[mfield]/j[cfield].replace(0,np.nan)
rows=[]
for key,g in j[j.year.isin(['2015','2019'])].groupby(['year','origin']):
 rows.append(dict(year=key[0],origin=key[1],rows=len(g),price_exact=int(g.price_exact.sum()),**{f'{field}_{kind}':int(g[f'{field}_{kind}'].sum()) for field in ['volume','OI'] for kind in ['positive','1x','2x']},volume_ratio_median=float(g.volume_ratio.median()),OI_ratio_median=float(g.OI_ratio.median())))
examples=[]
for key,g in j[j.year.isin(['2015','2019'])].groupby(['year','origin']):
 for kind in ['1x','2x']:
  q=g[g['volume_'+kind]&g['OI_'+kind]&g.price_exact].head(4)
  examples += q[['vt_symbol','date','contract_epoch_id','source_id','origin','volume_C','volume_M','close_oi','open_interest_M','volume_factor','oi_factor']].to_dict('records')
byprod=[]
for key,g in j[j.year.isin(['2015','2019'])].groupby(['year','product_vt','origin']):
 byprod.append({'year':key[0],'product':key[1],'origin':key[2],'rows':len(g),'volume_1x':int(g.volume_1x.sum()),'volume_2x':int(g.volume_2x.sum()),'OI_1x':int(g.OI_1x.sum()),'OI_2x':int(g.OI_2x.sum())})
# 2014 mapping physical-native join; distinguish no-market mappings from missing bars.
