for product,g in mapping.groupby('continuous_symbol_vt'):
 q=j14[j14.continuous_symbol_vt.eq(product)];mapstats.append({'product':product,'calendar_rows':len(g),'nonblank_mapping':len(q),'accepted_daily_found':int(q.contract_epoch_id.notna().sum()),'accepted_daily_missing':int(q.contract_epoch_id.isna().sum()),'first_nonblank':None if q.empty else q.date.min(),'first_available':None if not q.contract_epoch_id.notna().any() else q.loc[q.contract_epoch_id.notna(),'date'].min()})
