 q=warm[warm.vt_symbol.eq(r.main_contract_vt)];complete=[]
 for iso,g in q.groupby('iso'):
  expected=weeks[iso]
  if sorted(g.date.tolist())==expected and g.volume.gt(0).all():complete.append(expected[-1])
 readystats.append({'product':r.continuous_symbol_vt,'contract':r.main_contract_vt,'accepted_2014_daily':len(q),'complete_2014_weeks':len(complete),'ready21_from2014_only':len(complete)>=21,'last_2014_complete_week':max(complete) if complete else None})
