patchpath=SRC/'research/lines/futures_trend_rollover_shape_same_volume/outputs/stage278_daily_2015_20261022/data_review/historical_accepted_patch.csv';patch=pd.read_csv(patchpath);patch['vt_symbol']=patch.symbol+'.'+patch.exchange;patch['date']=patch.datetime.str[:10];missing=patch[[(r.vt_symbol,r.date) not in set(zip(m.vt_symbol,m.date)) for r in patch.itertuples()]]
result={'overlap_2015_2019':rows,'examples':examples,'by_product':byprod,'2014_accepted_rows':len(warm),'2014_contract_epochs':warm.contract_epoch_id.nunique(),'2014_nonpositive_volume':int(warm.volume.le(0).sum()),'2014_mapping_by_product':mapstats,'2014_mapped_real_daily_gaps':gaps[['date','continuous_symbol_vt','main_contract_vt']].to_dict('records'),'2015_first_mapping_warmup':readystats,'stage278_patch259_missing_in_M_pre2020_query':missing[['vt_symbol','date']].to_dict('records'),'notes':['Patch check query used M pre2020 rows;2020 patch keys must be checked separately before final number.','2014 last week crosses2015; this inventory cannot publish that partial week as complete before2015.']};Path('/private/tmp/stage022_units_result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k not in ['by_product','2014_mapped_real_daily_gaps']},ensure_ascii=False));print('2014_GAP_COUNT',len(gaps))
